mapper.select:
SELECT noti_seq AS noti_seq, noti_type_cd AS noti_type_cd, title AS title, TO_CHAR(start_dt, 'YYYY-MM-DD') AS start_dt, TO_CHAR(end_dt, 'YYYY-MM-DD') AS end_dt, COALESCE(pin_yn, 'N') AS pin_yn, COALESCE(popup_yn, 'N') AS popup_yn, COALESCE(view_cnt, 0) AS view_cnt, COALESCE(use_yn, 'Y') AS use_yn, TO_CHAR(updated_at, 'YYYY-MM-DD HH24:MI:SS') AS updated_at, updated_by AS updated_by, TO_CHAR(created_at, 'YYYY-MM-DD HH24:MI:SS') AS created_at, created_by AS created_by FROM adm_noti_mst WHERE 1=1
AND COALESCE(use_yn, 'Y') = #{use_yn}
AND COALESCE(use_yn, 'Y') = 'Y'
AND noti_type_cd = #{noti_type_cd}
AND title LIKE '%' || #{title} || '%'
ORDER BY COALESCE(pin_yn, 'N') DESC, COALESCE(start_dt, DATE '1900-01-01') DESC, noti_seq DESC

mapper.update:
UPDATE adm_noti_mst
   SET use_yn = 'N',
       updated_at = CURRENT_TIMESTAMP,
       updated_by = #{updated_by}
 WHERE noti_seq = #{noti_seq}
